update impianti set fl_disattivo=true where id_azienda=39;
update area_lavoro set fl_disattivo=true where id_impianto in (select id_impianto from impianti where id_azienda=39);
update equipment set fl_disattivo=true where id_area in (select id_area from area_lavoro where id_impianto in (select id_impianto from impianti where id_azienda=39 and fl_disattivo=true));




























